        Actuator2 := TRUE;
        Actuator3 := TRUE;
        SeqStep := 1;
    END_IF;
    1: IF VoteTrip OR LowPressureAlarm OR HighPressureAlarm THEN
        Actuator1 := FALSE;
        Actuator2 := FALSE;
        Actuator3 := FALSE;
